mapper.select:
SELECT * FROM wrong_question
WHERE student_id = #{studentId}

    AND course_id = #{courseId}

ORDER BY last_wrong_time DESC

SELECT COUNT(*) FROM wrong_question
WHERE student_id = #{studentId}

    AND course_id = #{courseId}

SELECT COUNT(*) FROM wrong_question
WHERE student_id = #{studentId}
AND is_mastered = 1

    AND course_id = #{courseId}

SELECT wq.*, q.id as q_id, q.type as q_type, q.content as q_content, q.options as q_options, q.answer as q_answer, q.analysis as q_analysis, c.course_name, ae.chapter FROM wrong_question wq LEFT JOIN ai_exam_questions q ON wq.question_id = q.id LEFT JOIN course c ON wq.course_id = c.id LEFT JOIN ai_exam ae ON wq.exam_id = ae.id WHERE wq.student_id = #{studentId}
AND wq.course_id = #{courseId}
ORDER BY wq.last_wrong_time DESC
